-- Re-sync the auto-increment sequences past the imported ids.
SELECT setval(pg_get_serial_sequence('readings', 'id'), COALESCE((SELECT MAX(id) FROM "readings"), 1), true);
SELECT setval(pg_get_serial_sequence('schedules', 'id'), COALESCE((SELECT MAX(id) FROM "schedules"), 1), true);
SELECT setval(pg_get_serial_sequence('pump_commands', 'id'), COALESCE((SELECT MAX(id) FROM "pump_commands"), 1), true);
SELECT setval(pg_get_serial_sequence('ai_insights', 'id'), COALESCE((SELECT MAX(id) FROM "ai_insights"), 1), true);

COMMIT;
